function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 500) return 'arr needs 1 to 500 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each value is an integer from 0 to 10^4.';
  return null;
}

