function sortByBits(arr) {
  const countBits = (value) => {
    let bits = 0;
    while (value > 0) {
      value &= value - 1;
      bits++;
    }
    return bits;
  };

  return arr.sort((a, b) => {
    const difference = countBits(a) - countBits(b);
    if (difference !== 0) {
      return difference;
    }
    return a - b;
  });
}

