function sortByBits(arr) {
  // Group by the number of '1' characters in the binary string, then join the sorted groups.
  const groups = [];
  for (const value of arr) {
    const ones = value.toString(2).split('').filter(c => c === '1').length;
    (groups[ones] ??= []).push(value);
  }
  const result = [];
  for (const group of groups) {
    if (!group) continue;
    const rest = group.slice();
    while (rest.length) {
      let smallest = 0;
      for (let i = 1; i < rest.length; i++) if (rest[i] < rest[smallest]) smallest = i;
      result.push(rest.splice(smallest, 1)[0]);
    }
  }
  return result;
}

