function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const n = 500;
    return [Array.from({ length: n }, () => pick(10001))];
  }
  const n = 1 + pick(10);
  const top = rand() < 0.5 ? 16 : 10001;
  return [Array.from({ length: n }, () => pick(top))];
}
